css:
:root {
  --rv-accent: oklch(0.4128 0.1233 255.65);
  --rv-accent-soft: oklch(0.4128 0.1233 255.65 / 0.122);
  --rv-bg: oklch(0.985 0.004 70);
  --rv-bg-chart: oklch(0.975 0.004 70);
  --rv-bg-elev: oklch(0.97 0.005 70);
  --rv-block-gap: 4rem;
  --rv-brand: oklch(0.4128 0.1233 255.65);
  --rv-chart-ink: oklch(0 0 0);
  --rv-density: 1;
  --rv-down: oklch(0.50 0.16 25);
  --rv-font-display: Big Shoulders, Arial Narrow, sans-serif;
  --rv-font-mono: Space Mono, ui-monospace, monospace;
  --rv-font-text: Newsreader, Georgia, Palatino Linotype, serif;
  --rv-font-ui: Space Mono, ui-monospace, monospace;
  --rv-hold: oklch(0.55 0.13 70);
  --rv-ink: oklch(0.16 0.005 70);
  --rv-ink-faint: oklch(0.62 0.008 70);
  --rv-ink-soft: oklch(0.40 0.006 70);
  --rv-line-base: 1.65;
  --rv-link: oklch(0.4128 0.1233 255.65);
  --rv-measure: 38rem;
  --rv-radius-m: 0px;
  --rv-radius-s: 0px;
  --rv-report-max-width: 880px;
  --rv-rule: oklch(0.16 0.005 70);
  --rv-rule-soft: oklch(0.88 0.004 70);
  --rv-shadow-float: none;
  --rv-size-base: 17px;
  --rv-size-display: 52px;
  --rv-size-h1: 34px;
  --rv-size-h2: 28px;
  --rv-size-h3: 21px;
  --rv-size-small: 14px;
  --rv-up: oklch(0.45 0.12 150);
}
@media (max-width: 640px) {
:root {
  --rv-block-gap: 2.5rem;
  --rv-size-base: 17px;
  --rv-size-display: 34px;
  --rv-size-h1: 30px;
  --rv-size-h2: 26px;
  --rv-size-h3: 21px;
  --rv-size-small: 14px;
}
}
:root{color-scheme:light}
:root{--rv-motion-duration:160ms;--rv-motion-easing:cubic-bezier(0.2,0,0,1);--rv-motion-stagger:0ms;--rv-motion-distance:0px;--rv-motion-block:none}
.rv-report__body blockquote{font-style:italic}
.rv-report__lede,.rv-report__subtitle{font-style:italic}
.rv-report__header{padding-top:calc(var(--rv-line) * .75);padding-bottom:var(--rv-line)}
.rv-metric{background:var(--rv-accent);border:2px solid var(--rv-ink);padding:calc(var(--rv-line) * .75 * var(--rv-density)) 1.25rem;color:oklch(1 0 0)}.rv-metric__value,.rv-metric__label,.rv-metric__delta,.rv-metric__delta--up,.rv-metric__delta--down{color:oklch(1 0 0)}
.rv-callout{border-top-width:2px}
.rv-report__header{border-top:4px solid var(--rv-ink)}
.rv-report__header{border-bottom:4px solid var(--rv-ink)}
.rv-report__title{text-transform:uppercase}
.rv-report__title{font-weight:800}
.rv-report__title{letter-spacing:0.02em}
.rv-report__body h1,.rv-report__body h2,.rv-report__body h3,.rv-callout__title,.rv-chart .rv-chart__title,.rv-chart-dialog__title{text-transform:uppercase}
.rv-report__body h1,.rv-report__body h2,.rv-report__body h3,.rv-callout__title,.rv-chart .rv-chart__title,.rv-chart-dialog__title{font-weight:800}
.rv-report__body h1,.rv-report__body h2,.rv-report__body h3,.rv-callout__title,.rv-chart .rv-chart__title,.rv-chart-dialog__title{letter-spacing:0.02em}
.rv-report__body th,.rv-chart-dialog th{text-transform:uppercase}
.rv-report__body th,.rv-chart-dialog th{font-weight:normal}
.rv-report__body th,.rv-chart-dialog th{letter-spacing:0.06em}
.rv-chart{border:2px solid var(--rv-ink);padding:1rem 1.25rem}
.rv-chart.rv-chart--expanded{border:0;background:none;border-radius:0}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
